@criterion(description="the quality register reports what the window boundary and the registers admitted, apart from the exception counts the upheld exception check owns")
def window_admission_and_quality(workspace: pathlib.Path) -> bool:
    owned = {"upheld_exception_count", "dismissed_exception_count"}
    quality = _read(workspace, "data_quality.json")
    if quality is None:
        return False
    delivered = {k: v for k, v in quality.items() if k not in owned}
    expected = {k: v for k, v in REFERENCE["data_quality.json"].items() if k not in owned}
    return delivered == expected


@criterion(description="the window record counts agree with the reference and sum to the eligible population")
def record_counts_close(workspace: pathlib.Path) -> bool:
    summary = _read(workspace, "summary.json")
    if summary is None:
        return False
    expected = REFERENCE["summary.json"]
    for key in (
        "landing_record_count",
        "in_window_record_count",
        "curated_record_count",
        "withdrawn_record_count",
        "curated_payload_units",
    ):
        if summary.get(key) != expected[key]:
            return False
    parts = [
        summary.get("curated_record_count"),
        summary.get("withdrawn_record_count"),
        summary.get("quarantined_record_count"),
    ]
    if any(not isinstance(p, int) or isinstance(p, bool) for p in parts):
        return False
    return sum(parts) == summary.get("in_window_record_count")


@criterion(description="every withdrawal reason count outside the cascade and tombstone reasons the quarantine and tombstone checks own matches the reference settlement")
def withdrawal_reasons_complete(workspace: pathlib.Path) -> bool:
    owned = {"withdrawn_by_quarantine_cascade", "withdrawn_by_tombstone"}
    summary = _read(workspace, "summary.json")
    if summary is None:
        return False
    reasons = summary.get("withdrawal_reason_counts")
    if not isinstance(reasons, dict):
        return False
    delivered = {token: count for token, count in reasons.items() if token not in owned}
    expected = {
        token: count
        for token, count in REFERENCE["summary.json"]["withdrawal_reason_counts"].items()
        if token not in owned
    }
    return delivered == expected


