# ---------------------------------------------------------------------------
# egress layer of the shipped window, rulebook_egress.md E1 to E7. One check per
# hidden decision, each reading only the field its own decision moves, so one
# wrong rule costs one check rather than a block of them.
# ---------------------------------------------------------------------------


def _egress_ref():
    return expected_egress(REFERENCE["ingest_audit.json"]["ledger"])


def _egress_text(workspace, name):
    try:
        return (_out(workspace) / name).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


@criterion(description="the egress account counts the curated records the burst rule retained and the records it held back")
def egress_counts_match_burst_decision(workspace: pathlib.Path) -> bool:
    # Scoped to the two counts. The pool (E2) and the digest (E7) are each
    # graded by their own check, so one wrong figure costs one check here
    # rather than taking this one down with it (CL-4).
    ref = _egress_ref()
    doc = _read(workspace, "egress_summary.json")
    if not isinstance(doc, dict):
        return False
    return (doc.get("retained_record_count") == len(ref["retained"])
            and doc.get("burst_record_count") == len(ref["bursts"]))


@criterion(description="every egress rate is the truncated quotient E1 states rather than a value placed on the settlement grid")
def egress_rate_truncates_not_places(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    doc = _read(workspace, "egress_rates.json")
    if not isinstance(doc, dict) or not isinstance(doc.get("rates"), list):
        return False
    want = {r["record_id"]: r["egress_rate"] for r in ref["rates"]}
    got = {r.get("record_id"): r.get("egress_rate") for r in doc["rates"]
           if isinstance(r, dict)}
    return got == want


@criterion(description="the egress rate artifact covers every curated record with its charge and payload units and covers no other record")
def egress_rates_cover_every_curated_record(workspace: pathlib.Path) -> bool:
    # Scoped to coverage and the fields carried forward from the settled
    # ledger. The E1 quotient on the same rows is graded by
    # egress_rate_truncates_not_places, so this no longer implies it (TS-26).
    carried = ("record_id", "feed_id", "domain_id", "payload_units",
               "record_charge_micros")
    ref = _egress_ref()
    doc = _read(workspace, "egress_rates.json")
    if not isinstance(doc, dict) or not isinstance(doc.get("rates"), list):
        return False
    want = [{k: r[k] for k in carried} for r in ref["rates"]]
    got = [{k: r.get(k) for k in carried} for r in doc["rates"]
           if isinstance(r, dict)]
    return got == want


@criterion(description="each burst record records the group median, the unscaled median absolute deviation and the threshold E2 builds from them")
def egress_burst_threshold_uses_mad(workspace: pathlib.Path) -> bool:
    # Scoped to the held-back set and the deviation and threshold E2 builds.
    # The E3 median on the same rows is graded by
    # egress_median_takes_lower_middle, so this no longer implies it (TS-26).
    keyed = ("record_id", "feed_id", "domain_id", "egress_rate",
             "group_mad", "threshold")
    ref = _egress_ref()
    doc = _read(workspace, "egress_bursts.json")
    if not isinstance(doc, dict) or not isinstance(doc.get("bursts"), list):
        return False
    want = [{k: r[k] for k in keyed} for r in ref["bursts"]]
    got = [{k: r.get(k) for k in keyed} for r in doc["bursts"]
           if isinstance(r, dict)]
    return bool(want) and got == want


@criterion(description="each group median is the lower of the two middle values of its even sample as E3 requires, not their mean")
def egress_median_takes_lower_middle(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    doc = _read(workspace, "egress_bursts.json")
    if not isinstance(doc, dict) or not isinstance(doc.get("bursts"), list):
        return False
    if not doc["bursts"]:
        return False
    want = {r["record_id"]: r["group_median"] for r in ref["bursts"]}
    got = {r.get("record_id"): r.get("group_median") for r in doc["bursts"]
           if isinstance(r, dict)}
    return got == want


@criterion(description="the egress pool sums the retained records alone, leaving every burst record out as E2 requires")
def egress_pool_excludes_bursts(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    doc = _read(workspace, "egress_summary.json")
    if not isinstance(doc, dict):
        return False
    return doc.get("egress_pool_micros") == ref["pool"]


@criterion(description="the egress order lists the retained records by ascending rate with ties broken by record identifier as E4 fixes")
def egress_order_is_ascending_rate(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    doc = _read(workspace, "egress_order.json")
    if not isinstance(doc, dict):
        return False
    return doc.get("order") == ref["order"]


@criterion(description="the egress digest is the positional sum over the emission order reduced by the modulus the platform publishes")
def egress_digest_matches_order(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    doc = _read(workspace, "egress_summary.json")
    if not isinstance(doc, dict):
        return False
    return doc.get("egress_digest") == ref["digest"]


@criterion(description="the payload apportionment hands every group a whole number of units and those units sum to the window's curated payload units")
def egress_apportionment_sums_to_curated_units(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    doc = _read(workspace, "egress_apportionment.json")
    if not isinstance(doc, dict):
        return False
    shares = doc.get("shares")
    if not isinstance(shares, dict) or not shares:
        return False
    values = list(shares.values())
    if not all(isinstance(v, int) and not isinstance(v, bool) for v in values):
        return False
    # The echo is anchored to the reference here because no other check
    # compares this artifact's curated_payload_units against the settled
    # figure; without that clause a self-consistent forgery earns the weight
    # (CL-2). The reference-share equality stays with the next check (TS-26).
    echoed = doc.get("curated_payload_units")
    if not isinstance(echoed, int) or isinstance(echoed, bool):
        return False
    if echoed != ref["curated_payload_units"]:
        return False
    return sum(values) == echoed


@criterion(description="each payload share is the largest remainder share E6 derives rather than an independently rounded proportion")
def egress_apportionment_matches_largest_remainder(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    doc = _read(workspace, "egress_apportionment.json")
    if not isinstance(doc, dict):
        return False
    return doc.get("shares") == dict(sorted(ref["shares"].items()))


@criterion(description="the egress rendering carries its header and one row per group with the retained count, the summed rate and the payload share")
def egress_ladder_rendering_matches_groups(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    text = _egress_text(workspace, LADDER_NAME)
    if text is None:
        return False
    want = "\n".join(["group_key,retained_count,group_rate_total,payload_share"] + [
        "%s,%d,%d,%d" % (key, ref["pod_count"][key], ref["pod_rate"][key],
                         ref["shares"][key])
        for key in sorted(ref["pod_rate"])]) + "\n"
    return text == want


@criterion(description="the egress account echoes the payload unit size in octets the rate was computed over")
def egress_summary_echoes_octets(workspace: pathlib.Path) -> bool:
    ref = _egress_ref()
    doc = _read(workspace, "egress_summary.json")
    if not isinstance(doc, dict):
        return False
    return doc.get("payload_unit_octets") == ref["payload_unit_octets"]


@criterion(description="every egress artifact names the window it settled")
def egress_artifacts_name_their_window(workspace: pathlib.Path) -> bool:
    # The schema puts window_id on all five egress objects. No other check
    # reads that field on them, and an egress account that cannot say which
    # window it belongs to is unusable beside the settlement it came from.
    want = REFERENCE["summary.json"]["window_id"]
    for name in EGRESS_ARTIFACTS:
        doc = _read(workspace, name)
        if not isinstance(doc, dict):
            return False
        if doc.get("window_id") != want:
            return False
    return True


EGRESS_SHAPE = {
    "egress_summary.json": ("egress_pool_micros", "egress_digest",
                            "retained_record_count", "burst_record_count",
                            "payload_unit_octets"),
    "egress_rates.json": ("rates",),
    "egress_bursts.json": ("bursts",),
    "egress_order.json": ("order",),
    "egress_apportionment.json": ("curated_payload_units", "shares"),
}


@criterion(description="every number the egress artifacts carry is a json integer with no floating point value among them")
def egress_artifacts_are_integers(workspace: pathlib.Path) -> bool:
    # The contracted keys are asserted before the scan, so an empty object
    # cannot pass by carrying no float: a forgery writing {} fails here.
    for name in EGRESS_ARTIFACTS:
        doc = _read(workspace, name)
        if not isinstance(doc, dict):
            return False
        if any(key not in doc for key in EGRESS_SHAPE[name]):
            return False
        stack = [doc]
        while stack:
            node = stack.pop()
            if isinstance(node, dict):
                stack.extend(node.values())
            elif isinstance(node, list):
                stack.extend(node)
            elif isinstance(node, float):
                return False
    return True


# ---------------------------------------------------------------------------
# generalisation. instruction.md makes settling a window the program has never
# seen a stated obligation, and each corpus below is one such window: its own
# registers, its own calibration block and its own egress policy register. Each
# check settles one corpus and compares the whole account the program wrote for
# it, so a figure wrong in one window costs that window alone.
# ---------------------------------------------------------------------------


